import math

def steps_needed(grad, x0, y0, step, tol, max_steps):
    x, y = x0, y0
    for k in range(max_steps):
        gx, gy = grad(x, y)
        if math.hypot(gx, gy) < tol:
            return k
        x, y = x - step * gx, y - step * gy
    return max_steps
